INSERT INTO repo_cf_skills (cf_skill_id, education_level, sub_heading, text, status) VALUES ('CFS_SDG06_TVET_006', 'TVET', 'Diagnostic and monitoring abilities', 'Conduct regular inspections and quality control checks on water and wastewater facilities.', 'Active'), ('CFS_SDG06_TVET_007', 'TVET', 'Diagnostic and monitoring abilities', 'Troubleshoot operational problems in water supply and treatment systems.', 'Active'), ('CFS_SDG06_TVET_008', 'TVET', 'Design and project implementation', 'Develop efficient workflows for water and waste management.', 'Active'), ('CFS_SDG06_TVET_009', 'TVET', 'Design and project implementation', 'Participate in designing systems for water reuse and energy-efficient sanitation solutions.', 'Active'), ('CFS_SDG06_TVET_010', 'TVET', 'Design and project implementation', 'Plan and implement sustainable recycling operations.', 'Active'), ('CFS_SDG06_TVET_011', 'TVET', 'Renewable energy and efficiency', 'Apply basic principles of solar, wind or hydro energy in water system applications.', 'Active'), ('CFS_SDG06_TVET_012', 'TVET', 'Renewable energy and efficiency', 'Assess water and energy use in treatment systems for sustainability improvements.', 'Active'), ('CFS_SDG06_TVET_013', 'TVET', 'Community and institutional engagement', 'Conduct awareness-raising activities in TVET institutions about water conservation and hygiene.', 'Active'), ('CFS_SDG06_TVET_014', 'TVET', 'Community and institutional engagement', 'Contribute to institutional greening efforts (for example, waste segregation, water-saving fixtures).', 'Active'), ('CFS_SDG06_TVET_015', 'TVET', 'Community and institutional engagement', 'Participate in field visits to water plants, recycling centres and infrastructure sites to observe best practices.', 'Active'), ('CFS_SDG06_TER_001', 'Tertiary education', 'Technical and engineering competencies', 'Operate, monitor and maintain machines and systems used in water production and wastewater treatment plants.', 'Active'), ('CFS_SDG06_TER_002', 'Tertiary education', 'Technical and engineering competencies', 'Conduct water audits for households, communities and institutions to measure usage patterns and promote conservation.', 'Active'), ('CFS_SDG06_TER_003', 'Tertiary education', 'Technical and engineering competencies', 'Implement and manage low-cost, scalable technologies for water harvesting, groundwater recharge and greywater reuse.', 'Active'), ('CFS_SDG06_TER_004', 'Tertiary education', 'Technical and engineering competencies', 'Develop and apply household or community-level FEW (food-energy-water) nexus models to assess the impact of environmental, social and technological drivers.', 'Active'), ('CFS_SDG06_TER_005', 'Tertiary education', 'Technical and engineering competencies', 'Design and maintain water distribution systems, including hydraulic modelling and leak detection strategies.', 'Active'), ('CFS_SDG06_TER_006', 'Tertiary education', 'Innovation and applied research', 'Engage in applied, interdisciplinary research to address water scarcity, especially in under-resourced and climate-vulnerable contexts such as small island developing states (SIDS).', 'Active'), ('CFS_SDG06_TER_007', 'Tertiary education', 'Innovation and applied research', 'Prototype and test financially sustainable water models, integrating tariffs, subsidies and demand-side management.', 'Active'), ('CFS_SDG06_TER_008', 'Tertiary education', 'Innovation and applied research', 'Use earth observation (EO) tools, GIS and remote sensing to monitor surface water, groundwater and watershed changes.', 'Active'), ('CFS_SDG06_TER_009', 'Tertiary education', 'Innovation and applied research', 'Innovate in climate adaptation strategies linked to water (for example, resilient infrastructure, early warning systems for floods and droughts).', 'Active'), ('CFS_SDG06_TER_010', 'Tertiary education', 'Innovation and applied research', 'Apply WPS (water, peace and security) tools to conduct conflict-sensitive assessments and design proactive water security interventions.', 'Active'), ('CFS_SDG06_TER_011', 'Tertiary education', 'Governance and policy analysis', 'Apply governance frameworks to analyse water rights, access equity and explore the implications of commodification versus public provision.', 'Active'), ('CFS_SDG06_TER_012', 'Tertiary education', 'Governance and policy analysis', 'Use ICT tools and open-access platforms to enhance transparency and accountability in water service delivery.', 'Active'), ('CFS_SDG06_TER_013', 'Tertiary education', 'Governance and policy analysis', 'Conduct policy simulations and stakeholder analyses to evaluate trade-offs in water allocation across domestic, agricultural, industrial and ecological uses.', 'Active'), ('CFS_SDG06_TER_014', 'Tertiary education', 'Governance and policy analysis', 'Design legal and institutional strategies for effective transboundary water management and compliance with international water laws.', 'Active'), ('CFS_SDG06_TER_015', 'Tertiary education', 'Data and decision-making', 'Collect, clean and interpret large water-related datasets, including disaggregated spatial and demographic data, to inform evidence-based decisions.', 'Active'), ('CFS_SDG06_TER_016', 'Tertiary education', 'Data and decision-making', 'Use data science techniques to model water demand, identify high-risk zones and simulate infrastructure stress under different climate scenarios.', 'Active'), ('CFS_SDG06_TER_017', 'Tertiary education', 'Data and decision-making', 'Develop indicators and dashboards for water monitoring systems, integrating biophysical, social and economic parameters.', 'Active'), ('CFS_SDG06_TER_018', 'Tertiary education', 'Data and decision-making', 'Apply spatial analysis to guide integrated urban and land-use planning for sustainable infrastructure development.', 'Active'), ('CFS_SDG06_TER_019', 'Tertiary education', 'Strategic and entrepreneurial skills', 'Conceptualise and implement entrepreneurial projects that introduce innovative water technologies or sanitation solutions to underserved communities.', 'Active'), ('CFS_SDG06_TER_020', 'Tertiary education', 'Strategic and entrepreneurial skills', 'Organise and manage recycling and waste management workflows, ensuring adherence to environmental and safety standards.', 'Active'), ('CFS_SDG06_TER_021', 'Tertiary education', 'Strategic and entrepreneurial skills', 'Develop climate-smart infrastructure projects, integrating renewable energy and circular economy principles into water systems.', 'Active'), ('CFS_SDG06_TER_022', 'Tertiary education', 'Strategic and entrepreneurial skills', 'Prepare business plans and grant proposals for water innovation projects with measurable social and environmental impact.', 'Active'), ('CFS_SDG06_TER_023', 'Tertiary education', 'Transdisciplinary and collaborative practice', 'Facilitate collaborative transdisciplinary research teams combining technical, ecological and social sciences.', 'Active'), ('CFS_SDG06_TER_024', 'Tertiary education', 'Transdisciplinary and collaborative practice', 'Use participatory methods for stakeholder engagement in water governance, especially in conflict-prone or marginalised areas.', 'Active'), ('CFS_SDG06_TER_025', 'Tertiary education', 'Transdisciplinary and collaborative practice', 'Engage in scenario-building and risk assessment exercises to explore water-related vulnerabilities and solutions at various scales.', 'Active'), ('CFS_SDG06_TER_026', 'Tertiary education', 'Transdisciplinary and collaborative practice', 'Integrate water security knowledge into disaster response planning and development programming across sectors.', 'Active'), ('CFS_SDG06_ADULT_001', 'Adult education', 'Personal and community hygiene and behavioural change', 'Practise and promote behavioural changes that optimise the benefits of clean water, such as handwashing, safe water storage and regular cleaning of sanitation facilities.', 'Active'), ('CFS_SDG06_ADULT_002', 'Adult education', 'Personal and community hygiene and behavioural change', 'Educate community members about the health benefits of using clean water and maintaining hygiene, reducing the spread of waterborne diseases.', 'Active'), ('CFS_SDG06_ADULT_003', 'Adult education', 'Personal and community hygiene and behavioural change', 'Teach sustainable water use habits, especially to younger generations, embedding water conservation as a lifelong value.', 'Active'), ('CFS_SDG06_ADULT_004', 'Adult education', 'Community organisation and leadership', 'Form and participate in village WASH (water, sanitation and hygiene) committees that promote inclusive decision-making with balanced gender representation.', 'Active'), ('CFS_SDG06_ADULT_005', 'Adult education', 'Community organisation and leadership', 'Organise and lead community awareness campaigns, such as small watershed conservation initiatives, tree planting for water catchment protection or water-saving demonstrations.', 'Active'), ('CFS_SDG06_ADULT_006', 'Adult education', 'Community organisation and leadership', 'Facilitate joint monitoring and training sessions to promote information sharing and build trust across community members and local institutions.', 'Active'), ('CFS_SDG06_ADULT_007', 'Adult education', 'Water efficiency and conservation', 'Apply practical skills in WASH, such as constructing and maintaining latrines, managing waste safely, and treating household water through simple filtration or boiling.', 'Active'), ('CFS_SDG06_ADULT_008', 'Adult education', 'Water efficiency and conservation', 'Use and teach low-cost technologies for improving water efficiency in homes and farms, such as drip irrigation, mulching and rainwater harvesting systems.', 'Active'), ('CFS_SDG06_ADULT_009', 'Adult education', 'Water efficiency and conservation', 'Implement agricultural water-saving techniques and practices that avoid contamination of waterways from chemical runoff or livestock waste.', 'Active'), ('CFS_SDG06_ADULT_010', 'Adult education', 'Watershed and resource management', 'Apply watershed management techniques to conserve local water sources, including erosion control, catchment protection and reforestation.', 'Active'), ('CFS_SDG06_ADULT_011', 'Adult education', 'Watershed and resource management', 'Soil and water resource management, including water harvesting, storage and reuse for household or farming use.', 'Active'), ('CFS_SDG06_ADULT_012', 'Adult education', 'Watershed and resource management', 'Apply freshwater conservation practices and contribute to local projects that restore and protect community water bodies.', 'Active'), ('CFS_SDG06_ADULT_013', 'Adult education', 'Climate resilience', 'Apply human ecology and environmental resilience to create sustainable water use strategies that adapt to climate-related water scarcity or floods.', 'Active'), ('CFS_SDG06_ADULT_014', 'Adult education', 'Climate resilience', 'Develop and support community water management systems for local resilience to climate change impacts.', 'Active') ON CONFLICT DO NOTHING;